/** Most of a description the first message carries: the summary lines above it stay in view, and Discord's own limit is 2000 characters. */
export const DESCRIPTION_LIMIT = 1500;

/** What Sourcery writes between its start and end markers, e.g. the reviewer's guide. */
const SOURCERY_BLOCK =
	/<!--\s*Generated by sourcery-ai[^>]*?start\s+(\w+)\s*-->[\s\S]*?<!--\s*Generated by sourcery-ai[^>]*?end\s+\1\s*-->/gi;

/** Sourcery's auto-generated summary starts at this marker and runs to the end of the description. */
const SOURCERY_SUMMARY = /<!--\s*This is an auto-generated description by sourcery-ai\.?\s*-->[\s\S]*$/i;

/** A command someone typed to Sourcery (`@sourcery-ai summary`). */
const SOURCERY_COMMAND = /^.*@sourcery-ai\b.*$/gim;

/** Drops each heading that names Sourcery with its section, up to the next heading of the same or a higher level. */
function withoutSourcerySections(text: string): string {
	const kept: string[] = [];
	let skipping = 0;
	for (const line of text.split("\n")) {
		const heading = /^(#{1,6})\s/.exec(line);
		if (heading) {
			const level = heading[1]!.length;
			if (/sourcery/i.test(line)) {
				skipping = level;
				continue;
			}
			if (skipping > 0 && level <= skipping) skipping = 0;
		}
		if (skipping === 0) kept.push(line);
	}
	return kept.join("\n");
}

/**
 * The part of a pull request's description worth showing in its post: the text the author wrote. Sourcery's summary,
 * reviewer's guide and commands are removed, and so is every HTML comment (a template's hints), the blank runs they
 * leave are closed up, and what is left is cut to {@link DESCRIPTION_LIMIT} characters with an ellipsis. A description
 * with nothing left, or none, is an empty string.
 */
export function prDescription(body: string | null | undefined): string {
	if (!body) return "";
	const text = withoutSourcerySections(
		body.replace(/\r\n?/g, "\n").replace(SOURCERY_BLOCK, "").replace(SOURCERY_SUMMARY, "")
	)
		.replace(SOURCERY_COMMAND, "")
		.replace(/<!--[\s\S]*?-->/g, "")
		.replace(/\n{3,}/g, "\n\n")
		.trim();
	return text.length <= DESCRIPTION_LIMIT ? text : `${text.slice(0, DESCRIPTION_LIMIT - 1).trimEnd()}…`;
}
